//! Tests for `pr_core::file_actions::journal_line` (port of `PhotoReview.Core/FileActions/JournalLineParser.cs` and the
//! `JournalEntry` / `JournalGroupMember` line shape). The golden file `tests/golden/journal-lines.json` is generated by
//! the C# oracle (`tools/oracle-cs/Commands/W1-14.cs`) and is checked case by case.

use pr_core::file_actions::journal_line::{
    JournalDateTime, JournalEntry, JournalGroupMember, try_parse, try_parse_utf8,
};
use pr_core::model::{FileOperationType, JournalState};
use pr_test_support::golden::{self, str_of};
use serde_json::{Value, json};

// ---------------------------------------------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------------------------------------------

/// C# `Stamp` of the group tests: `new DateTime(2026, 9, 29, 0, 0, 0, DateTimeKind.Utc)`.
fn stamp() -> JournalDateTime {
    JournalDateTime::parse_json("2026-09-29T00:00:00Z").expect("stamp text parses")
}

fn member(source: &str, destination: &str, size: i64) -> JournalGroupMember {
    JournalGroupMember {
        source: source.to_owned(),
        destination: Some(destination.to_owned()),
        size,
        last_write_utc: stamp(),
        permanent: false,
    }
}

/// C# `GroupPrepared(id, members)`: the top level is the first member, group id `capture-<id>`.
fn group_prepared(id: &str, members: Vec<JournalGroupMember>) -> JournalEntry {
    let first = members.first().cloned().expect("a group has at least one member");
    JournalEntry {
        id: id.to_owned(),
        op_type: FileOperationType::Move,
        state: JournalState::Prepared,
        source: first.source,
        destination: first.destination,
        size: first.size,
        last_write_utc: stamp(),
        timestamp_utc: stamp(),
        error: None,
        error_code: None,
        permanent: None,
        undo: None,
        group_id: Some(format!("capture-{id}")),
        group_members: Some(members),
    }
}

/// C# `Members` of the group tests.
fn default_members() -> Vec<JournalGroupMember> {
    vec![
        member(r"C:\photos\a.jpg", r"C:\selected\a.jpg", 10),
        member(r"C:\photos\a.cr2", r"C:\selected\a.cr2", 100),
    ]
}

/// C# `JournalBlankPathTests.Line(source, destination)`.
fn blank_path_line(source: &str, destination: Option<&str>) -> String {
    format!(
        "{{\"Id\":\"id1\",\"Type\":\"Move\",\"State\":\"Prepared\",\"Source\":{},\"Destination\":{},\"Size\":1,\"LastWriteUtc\":\"2026-01-01T00:00:00Z\",\"TimestampUtc\":\"2026-01-01T00:00:00Z\"}}",
        serde_json::to_string(source).expect("string serializes"),
        serde_json::to_string(&destination).expect("option serializes"),
    )
}

fn type_name(t: FileOperationType) -> &'static str {
    match t {
        FileOperationType::Move => "Move",
        FileOperationType::Copy => "Copy",
        FileOperationType::Recycle => "Recycle",
    }
}

fn state_name(s: JournalState) -> &'static str {
    match s {
        JournalState::Prepared => "Prepared",
        JournalState::Committed => "Committed",
        JournalState::Failed => "Failed",
        JournalState::Dismissed => "Dismissed",
    }
}

fn kind_name(d: JournalDateTime) -> &'static str {
    if d.unspecified { "Unspecified" } else { "Utc" }
}

/// The JSON shape the C# oracle writes for a timestamp (`{ticks, kind}`).
fn datetime_json(d: JournalDateTime) -> Value {
    json!({ "ticks": d.value.ticks(), "kind": kind_name(d) })
}

fn member_json(m: &JournalGroupMember) -> Value {
    json!({
        "source": m.source,
        "destination": m.destination,
        "size": m.size,
        "last_write": datetime_json(m.last_write_utc),
        "permanent": m.permanent,
    })
}

/// The JSON shape of `JournalEntryJson` in the C# oracle.
fn entry_json(e: &JournalEntry) -> Value {
    json!({
        "id": e.id,
        "type": type_name(e.op_type),
        "state": state_name(e.state),
        "source": e.source,
        "destination": e.destination,
        "size": e.size,
        "last_write": datetime_json(e.last_write_utc),
        "timestamp": datetime_json(e.timestamp_utc),
        "error": e.error,
        "error_code": e.error_code,
        "permanent": e.permanent,
        "undo": e.undo,
        "group_id": e.group_id,
        "group_members": e.group_members.as_ref().map(|members| members.iter().map(member_json).collect::<Vec<_>>()),
    })
}

fn op_type_from(name: &str) -> FileOperationType {
    match name.to_ascii_lowercase().as_str() {
        "move" => FileOperationType::Move,
        "copy" => FileOperationType::Copy,
        "recycle" => FileOperationType::Recycle,
        other => panic!("golden type {other:?}"),
    }
}

fn state_from(name: &str) -> JournalState {
    match name.to_ascii_lowercase().as_str() {
        "prepared" => JournalState::Prepared,
        "committed" => JournalState::Committed,
        "failed" => JournalState::Failed,
        "dismissed" => JournalState::Dismissed,
        other => panic!("golden state {other:?}"),
    }
}

/// Integers in the writer cases are JSON strings (`"4823911"`); the line cases use JSON numbers.
fn int_of(v: &Value) -> i64 {
    match v {
        Value::String(s) => s.parse().unwrap_or_else(|_| panic!("golden integer {s:?}")),
        other => other.as_i64().unwrap_or_else(|| panic!("golden integer {other}")),
    }
}

fn opt_string(v: &Value) -> Option<String> {
    v.as_str().map(str::to_owned)
}

fn datetime_from(v: &Value) -> JournalDateTime {
    let ticks = int_of(&v["ticks"]);
    let value = pr_core::time::DateTimeUtc::from_ticks(ticks).unwrap_or_else(|| panic!("golden ticks {ticks}"));
    if v["kind"]
        .as_str()
        .is_some_and(|k| k.eq_ignore_ascii_case("unspecified"))
    {
        JournalDateTime::unspecified(value)
    } else {
        JournalDateTime::utc(value)
    }
}

/// Builds the entry of a writer case (`JournalEntryFrom` in the C# oracle).
fn entry_from(v: &Value) -> JournalEntry {
    JournalEntry {
        id: str_of(v, "id").to_owned(),
        op_type: op_type_from(str_of(v, "type")),
        state: state_from(str_of(v, "state")),
        source: str_of(v, "source").to_owned(),
        destination: opt_string(&v["destination"]),
        size: int_of(&v["size"]),
        last_write_utc: datetime_from(&v["last_write"]),
        timestamp_utc: datetime_from(&v["timestamp"]),
        error: opt_string(&v["error"]),
        error_code: opt_string(&v["error_code"]),
        permanent: v["permanent"].as_bool(),
        undo: v["undo"].as_bool(),
        group_id: opt_string(&v["group_id"]),
        group_members: v["group_members"].as_array().map(|members| {
            members
                .iter()
                .map(|m| JournalGroupMember {
                    source: str_of(m, "source").to_owned(),
                    destination: opt_string(&m["destination"]),
                    size: int_of(&m["size"]),
                    last_write_utc: datetime_from(&m["last_write"]),
                    permanent: m["permanent"]
                        .as_bool()
                        .unwrap_or_else(|| panic!("golden member permanent {m}")),
                })
                .collect()
        }),
    }
}

/// Hex text of the `byte_lines_hex` cases.
fn hex_bytes(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap_or_else(|_| panic!("golden hex {hex}")))
        .collect()
}

/// Deterministic xorshift64 generator (no dependency, same sequence on every run).
struct Rng(u64);

impl Rng {
    fn next_u64(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }

    fn below(&mut self, n: usize) -> usize {
        (self.next_u64() % n as u64) as usize
    }
}

// ---------------------------------------------------------------------------------------------------------------
// Golden: every case of tests/golden/journal-lines.json
// ---------------------------------------------------------------------------------------------------------------

/// Checks one parse case: accept/reject, the parsed entry as the C# oracle wrote it, and the C# re-serialization.
fn check_parse_case(case: &Value, parsed: Option<&JournalEntry>, index: usize) {
    let ok = case["ok"]
        .as_bool()
        .unwrap_or_else(|| panic!("case {index} has no ok: {case}"));
    assert_eq!(parsed.is_some(), ok, "case {index} accept/reject: {case}");
    if let Some(entry) = parsed {
        assert_eq!(entry_json(entry), case["entry"], "case {index} entry: {case}");
        assert_eq!(
            entry.to_line(),
            str_of(case, "reserialized"),
            "case {index} reserialized: {case}"
        );
    }
}

// C#: JournalLineParserTests.TryParse_HandWrittenCorpus_MatchesLegacy (+ the byte and writer rows of the same
// oracle, see tools/oracle-cs/Commands/W1-14.cs).
#[test]
fn journal_lines_match_golden() {
    let g = golden::load("journal-lines");
    assert_eq!(g.generator, "oracle-cs journal-lines");
    let mut parse_cases = 0usize;
    let mut writer_cases = 0usize;
    for (index, case) in g.cases.iter().enumerate() {
        match str_of(case, "kind") {
            "line" => {
                let line = str_of(case, "line");
                let parsed = try_parse(line);
                assert_eq!(
                    try_parse_utf8(line.as_bytes()),
                    parsed,
                    "case {index}: string and byte overloads disagree: {line}"
                );
                check_parse_case(case, parsed.as_ref(), index);
                parse_cases += 1;
            }
            "bytes" => {
                let bytes = hex_bytes(str_of(case, "hex"));
                let parsed = try_parse_utf8(&bytes);
                check_parse_case(case, parsed.as_ref(), index);
                parse_cases += 1;
            }
            "write" => {
                let entry = entry_from(&case["entry"]);
                assert_eq!(entry.to_line(), str_of(case, "line"), "case {index} writer line");
                writer_cases += 1;
            }
            other => panic!("case {index}: unknown kind {other:?}"),
        }
    }
    assert_eq!(parse_cases, 317, "golden parse cases (301 lines + 16 raw-byte lines)");
    assert_eq!(writer_cases, 24, "golden writer cases");
}

