// C#: JournalLineParserTests.TryParse_InvalidUtf8Bytes_ReturnsNull
#[test]
fn try_parse_invalid_utf8_bytes_returns_none() {
    let invalid: [u8; 7] = [0x7B, 0x22, 0x49, 0x64, 0xFF, 0xFE, 0x22];
    assert!(try_parse_utf8(&invalid).is_none());
}

// C#: JournalLineParserTests.TryParse_CommaListEnumText_IsRejected (W2-FA-01)
#[test]
fn try_parse_comma_list_enum_text_is_rejected() {
    let rows = [
        ("Move", "Prepared,Committed"),
        ("Recycle", "Prepared,Committed"),
        ("Move,Recycle", "Prepared"),
        ("Move", "Committed,Failed"),
    ];
    for (type_text, state_text) in rows {
        let line = format!(
            "{{\"Id\":\"id1\",\"Type\":\"{type_text}\",\"State\":\"{state_text}\",\"Source\":\"C:\\\\a.jpg\",\"Destination\":null,\"Size\":1,\"LastWriteUtc\":\"2026-01-01T00:00:00Z\",\"TimestampUtc\":\"2026-01-01T00:00:00Z\"}}"
        );
        assert!(try_parse(&line).is_none(), "{line}");
        assert!(try_parse_utf8(line.as_bytes()).is_none(), "{line}");
    }
}

// C#: JournalLineParserTests.TryParse_SeededFuzz_MatchesLegacyOverManyLines (lite: the legacy two-pass oracle is not
// ported; this checks that both overloads agree and that nothing panics over 3000 generated lines).
#[test]
fn try_parse_seeded_fuzz_overloads_agree_and_never_panic() {
    const TYPE_VARIANTS: &[&str] = &[
        "\"Move\"",
        "\"Copy\"",
        "\"Recycle\"",
        "\"delete\"",
        "\"DELETE\"",
        "\" Delete \"",
        "0",
        "1",
        "2",
        "3",
        "-1",
        "1.5",
        "2147483648",
        "\"1\"",
        "\" 2 \"",
        "\"Move, Copy\"",
        "\"Rename\"",
        "\"\"",
        "null",
        "{}",
        "[]",
        "true",
    ];
    const STATE_VARIANTS: &[&str] = &[
        "\"Prepared\"",
        "\"Committed\"",
        "\"Failed\"",
        "\"Dismissed\"",
        "0",
        "1",
        "2",
        "3",
        "4",
        "-1",
        "2.5",
        "\"1\"",
        "\" 2 \"",
        "\"Bogus\"",
        "\"\"",
        "null",
        "{}",
        "[]",
        "false",
    ];
    const ID_VARIANTS: &[Option<&str>] = &[Some("\"id1\""), Some("\"\""), Some("null"), None];
    const SOURCE_VARIANTS: &[Option<&str>] = &[Some("\"C:\\\\a.jpg\""), Some("null"), None];
    const DESTINATION_VARIANTS: &[&str] = &["\"C:\\\\b.jpg\"", "null"];
    const SIZE_VARIANTS: &[&str] = &["1", "\"123\"", "0"];
    const TIMESTAMP: &str = "\"2026-01-01T00:00:00Z\"";

    let mut rng = Rng(0x9E37_79B9_7F4A_7C15);
    let mut accepted = 0usize;
    let mut rejected = 0usize;
    for _ in 0..3000 {
        let mut parts: Vec<String> = Vec::new();
        if let Some(Some(id)) = ID_VARIANTS.get(rng.below(ID_VARIANTS.len())) {
            parts.push(format!("\"Id\":{id}"));
        }
        parts.push(format!("\"Type\":{}", TYPE_VARIANTS[rng.below(TYPE_VARIANTS.len())]));
        if rng.below(6) == 0 {
            parts.push(format!("\"Type\":{}", TYPE_VARIANTS[rng.below(TYPE_VARIANTS.len())]));
        }
        parts.push(format!("\"State\":{}", STATE_VARIANTS[rng.below(STATE_VARIANTS.len())]));
        if rng.below(6) == 0 {
            parts.push(format!("\"State\":{}", STATE_VARIANTS[rng.below(STATE_VARIANTS.len())]));
        }
        if let Some(Some(source)) = SOURCE_VARIANTS.get(rng.below(SOURCE_VARIANTS.len())) {
            parts.push(format!("\"Source\":{source}"));
        }
        parts.push(format!(
            "\"Destination\":{}",
            DESTINATION_VARIANTS[rng.below(DESTINATION_VARIANTS.len())]
        ));
        parts.push(format!("\"Size\":{}", SIZE_VARIANTS[rng.below(SIZE_VARIANTS.len())]));
        parts.push(format!("\"LastWriteUtc\":{TIMESTAMP}"));
        parts.push(format!("\"TimestampUtc\":{TIMESTAMP}"));
        if rng.below(8) == 0 {
            parts.push("\"Extra\":\"noise\"".to_owned());
        }
        // Fisher-Yates shuffle: "last one wins" must also hold for non-adjacent duplicates.
        for i in (1..parts.len()).rev() {
            let j = rng.below(i + 1);
            parts.swap(i, j);
        }
        let line = format!("{{{}}}", parts.join(","));
        let line = match rng.below(20) {
            0 => line.get(..line.len() / 2).unwrap_or(&line).to_owned(),
            1 => format!("{line}garbage"),
            2 => "{".to_owned(),
            3 => String::new(),
            _ => line,
        };

        let from_text = try_parse(&line);
        let from_bytes = try_parse_utf8(line.as_bytes());
        assert_eq!(from_bytes, from_text, "overloads disagree: {line}");
        if from_text.is_some() {
            accepted += 1;
        } else {
            rejected += 1;
        }
    }
    assert!(
        accepted > 0 && rejected > 0,
        "fuzz covers both outcomes (accepted {accepted}, rejected {rejected})"
    );
}

