// C#: JournalBlankPathTests.TryParse_BlankOrNulSource_IsRejected
#[test]
fn try_parse_blank_or_nul_source_is_rejected() {
    for source in ["", "   ", "\0"] {
        let line = blank_path_line(source, Some(r"C:\b.jpg"));
        assert!(try_parse(&line).is_none(), "source {source:?}: {line}");
        assert!(try_parse_utf8(line.as_bytes()).is_none(), "source {source:?}: {line}");
    }
}

// C#: JournalBlankPathTests.TryParse_BlankDestination_IsReadAsNull
#[test]
fn try_parse_blank_destination_is_read_as_null() {
    for destination in ["", "  ", "\0"] {
        let line = blank_path_line(r"C:\a.jpg", Some(destination));
        let entry = try_parse(&line).unwrap_or_else(|| panic!("accepted: {line}"));
        assert_eq!(entry.destination, None, "destination {destination:?}");
    }
}

// C#: JournalBlankPathTests.TryParse_ValidLine_IsAccepted
#[test]
fn try_parse_valid_line_is_accepted() {
    let line = blank_path_line(r"C:\a.jpg", Some(r"C:\b.jpg"));
    let entry = try_parse(&line).expect("valid line is accepted");
    assert_eq!(entry.destination.as_deref(), Some(r"C:\b.jpg"));
    assert_eq!(try_parse_utf8(line.as_bytes()), Some(entry));
}

