// C#: JournalGroupEvidenceAndNulMemberTests.TryParse_NulInMemberPath_IsRejected (W2-FA-07)
#[test]
fn try_parse_nul_in_member_path_is_rejected() {
    let rows = [("a\0.jpg", r"C:\selected\a.jpg"), (r"C:\photos\a.jpg", "b\0.jpg")];
    for (source, destination) in rows {
        let mut members = vec![member(source, destination, 1)];
        members.push(default_members()[1].clone());
        let line = group_prepared("n", members).to_line();
        assert!(try_parse(&line).is_none(), "{line}");
        assert!(try_parse_utf8(line.as_bytes()).is_none(), "{line}");
    }
    let good = group_prepared("ok", default_members()).to_line();
    assert!(try_parse(&good).is_some(), "{good}");
}

// C#: JournalGroupReconcileTests.TryParse_GroupLineWithNullMemberOrBlankSource_IsRejected
// Rows `GroupGood`, `GroupNullMember`, `GroupBlankSource` are golden cases (`journal-lines.json`); the null-member
// rule is also checked directly below.
#[test]
fn try_parse_group_line_with_null_member_is_rejected() {
    let good = group_prepared("good", default_members()).to_line();
    assert!(try_parse(&good).is_some(), "{good}");
    let null_member = good.replacen("\"GroupMembers\":[", "\"GroupMembers\":[null,", 1);
    assert_ne!(null_member, good);
    assert!(try_parse(&null_member).is_none(), "{null_member}");
    assert!(try_parse_utf8(null_member.as_bytes()).is_none(), "{null_member}");
}

