// C#: JournalGroupSchemaTests.SingleFileEntry_KeepsLegacyJsonShapeAndParsesWithoutGroupMetadata
#[test]
fn single_file_entry_keeps_legacy_json_shape_and_parses_without_group_metadata() {
    let entry = JournalEntry {
        id: "single".to_owned(),
        op_type: FileOperationType::Move,
        state: JournalState::Prepared,
        source: r"C:\photos\a.jpg".to_owned(),
        destination: Some(r"C:\photos\selected\a.jpg".to_owned()),
        size: 12,
        last_write_utc: stamp(),
        timestamp_utc: stamp(),
        error: None,
        error_code: None,
        permanent: None,
        undo: None,
        group_id: None,
        group_members: None,
    };

    let json = entry.to_line();
    let parsed = try_parse(&json).expect("single-file line parses");

    assert!(!json.contains("GroupId"), "{json}");
    assert!(!json.contains("GroupMembers"), "{json}");
    assert_eq!(parsed.group_id, None);
    assert_eq!(parsed.group_members, None);
    assert_eq!(parsed, entry);
}

// C#: JournalGroupSchemaTests.GroupEntry_ReadByOlderBuild_LooksLikeASingleMoveOfTheFirstMember
#[test]
fn group_entry_read_by_older_build_looks_like_single_move_of_first_member() {
    // A build without group support skips the unknown GroupId/GroupMembers members and sees ONE Move whose top-level
    // fields are the FIRST member's.
    let members = vec![
        member(r"C:\photos\a.jpg", r"C:\photos\selected\a.jpg", 12),
        member(r"C:\photos\a.cr2", r"C:\photos\selected\a.cr2", 120),
    ];
    let entry = JournalEntry {
        state: JournalState::Committed,
        group_id: Some("capture-a".to_owned()),
        ..group_prepared("group", members.clone())
    };

    let value: Value = serde_json::from_str(&entry.to_line()).expect("line is JSON");

    assert_eq!(value["Source"], json!(members[0].source));
    assert_eq!(value["Destination"], json!(members[0].destination));
    assert_eq!(value["Size"], json!(members[0].size));
}

// C#: JournalGroupSchemaTests.GroupEntry_RoundTripsAllMemberFingerprintsAndDestinations
#[test]
fn group_entry_round_trips_all_member_fingerprints_and_destinations() {
    let members = vec![
        member(r"C:\photos\a.jpg", r"C:\photos\selected\a.jpg", 12),
        member(r"C:\photos\a.cr2", r"C:\photos\selected\a.cr2", 120),
        member(r"C:\photos\a.xmp", r"C:\photos\selected\a.xmp", 4),
    ];
    let entry = group_prepared("group", members.clone());

    let parsed = try_parse(&entry.to_line()).expect("group line parses");

    assert_eq!(parsed.id, entry.id);
    assert_eq!(parsed.group_id, entry.group_id);
    let read = parsed.group_members.expect("members are read back");
    let sources: Vec<&str> = read.iter().map(|m| m.source.as_str()).collect();
    assert_eq!(sources, [r"C:\photos\a.jpg", r"C:\photos\a.cr2", r"C:\photos\a.xmp"]);
    let sizes: Vec<i64> = read.iter().map(|m| m.size).collect();
    assert_eq!(sizes, [12, 120, 4]);
    assert_eq!(read, members);
}

