// C#: JournalTailCommittedMoveTests.TryParseTailCommittedMove_LineTheFullReaderRejects_IsQuarantinedHereToo
// The `JournalLineParser` half: the `Tail*` rows are golden cases (journal-lines.json). The tail-reader half belongs
// to the journal unit.

// ---------------------------------------------------------------------------------------------------------------
// Depth limit (the spec of this unit, not a port of a single C# test)
// ---------------------------------------------------------------------------------------------------------------

/// `{"Id":..., "Extra": [[[...]]]}` with `containers` nested containers including the top-level object.
fn line_with_depth(containers: usize) -> String {
    let nest = containers - 1;
    let mut extra = String::new();
    for _ in 0..nest {
        extra.push('[');
    }
    for _ in 0..nest {
        extra.push(']');
    }
    format!(
        "{{\"Id\":\"id1\",\"Type\":\"Move\",\"State\":\"Prepared\",\"Source\":\"C:\\\\a.jpg\",\"Destination\":null,\"Size\":1,\"LastWriteUtc\":\"2026-01-01T00:00:00Z\",\"TimestampUtc\":\"2026-01-01T00:00:00Z\",\"Extra\":{extra}}}"
    )
}

#[test]
fn nesting_depth_64_is_accepted_and_65_is_rejected() {
    let at_limit = line_with_depth(64);
    assert!(try_parse(&at_limit).is_some(), "depth 64 accepted");
    assert!(
        try_parse_utf8(at_limit.as_bytes()).is_some(),
        "depth 64 accepted (bytes)"
    );
    let over_limit = line_with_depth(65);
    assert!(try_parse(&over_limit).is_none(), "depth 65 rejected");
    assert!(
        try_parse_utf8(over_limit.as_bytes()).is_none(),
        "depth 65 rejected (bytes)"
    );
}

